# Les k valeurs les plus fréquentes (départage par valeur croissante).
def top_k_frequent(nums, k):
    counts = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1
    # BUG : trie seulement par fréquence, sans départage stable par valeur.
    ordered = sorted(counts, key=lambda v: -counts[v])
    return ordered[:k]

